        throw new IllegalArgumentException("File name cannot be null or empty");
    }
    File file = new File(fileName);
    if (file.exists()) {
        if (!file.delete()) {
            throw new RuntimeException("Failed to delete file: " + fileName);
        }
    }
}

protected static void deleteFile(String fileName) {
    if (fileName == null || fileName.trim().isEmpty()) {
        return; // No need to attempt deletion if the filename is null or empty
    }

    java.io.File file = new java.io.File(fileName);
    if (file.exists()) {
        if (file.delete()) {
            System.out.println("File deleted successfully: " + fileName);
        } else {
            System.err.println("Failed to delete the file: " + fileName);
        }
    } else {
        System.out.println("File does not exist: " + fileName);
    }
}

protected static void deleteFile(String fileName){
    if (fileName == null || fileName.isEmpty()) {
        throw new IllegalArgumentException("File name cannot be null or empty");
    }
    try {
        java.io.File file = new java.io.File(fileName);
        if (file.exists()) {
            if (!file.delete()) {
                throw new java.io.IOException("Failed to delete the file: " + fileName);
            }
        }
    } catch (SecurityException se) {
        throw new java.io.IOException("Permission denied to delete the file: " + fileName, se);
    } catch (java.io.IOException ioe) {
        throw new java.io.IOException("An error occurred while trying to delete the file: " + fileName, ioe);
    }
}

public static int nullSafeHashCode(long[] array){
    if (array == null) {
        return 0;
    }
    int result = 1;
    for (long element : array) {
        result = 31 * result + (int) (element ^ (element >>> 32));
    }
    return result;
}

