private int parseEndOfLine(String headerPart, int end) {
    if (headerPart == null || end < 0 || end >= headerPart.length()) {
        throw new IllegalArgumentException("Invalid input: headerPart cannot be null and end must be a valid index within headerPart.");
    }

    for (int i = end; i < headerPart.length() - 1; i++) {
        if (headerPart.charAt(i) == '\r' && headerPart.charAt(i + 1) == '\n') {
            return i;
        }
    }

    // If no \r\n sequence is found, return -1 to indicate the end of line was not found
    return -1;
}

