public static <V,E>IsomorphicGraphMapping<V,E> identity(Graph<V,E> graph){
    if (graph == null) {
        throw new IllegalArgumentException("Graph cannot be null");
    }
    return new IsomorphicGraphMapping<V,E>(graph, graph) {
        @Override
        public V getVertexCorrespondence(V vertex, boolean forward) {
            if (vertex == null) {
                throw new IllegalArgumentException("Vertex cannot be null");
            }
            return vertex;
        }

        @Override
        public E getEdgeCorrespondence(E edge, boolean forward) {
            if (edge == null) {
                throw new IllegalArgumentException("Edge cannot be null");
            }
            return edge;
        }
    };
}

public static <V,E>IsomorphicGraphMapping<V,E> identity(Graph<V,E> graph){
    if (graph == null) {
        throw new IllegalArgumentException("Graph cannot be null");
    }
    return new IsomorphicGraphMapping<V, E>() {
        @Override
        public V getVertexCorrespondence(V vertex, boolean forward) {
            if (vertex == null) {
                throw new IllegalArgumentException("Vertex cannot be null");
            }
            if (!graph.containsVertex(vertex)) {
                throw new IllegalArgumentException("Vertex is not in the graph");
            }
            return vertex;
        }

        @Override
        public E getEdgeCorrespondence(E edge, boolean forward) {
            if (edge == null) {
                throw new IllegalArgumentException("Edge cannot be null");
            }
            if (!graph.containsEdge(edge)) {
                throw new IllegalArgumentException("Edge is not in the graph");
            }
            return edge;
        }

        @Override
        public int getVertexCount() {
            return graph.vertexSet().size();
        }

        @Override
        public int getEdgeCount() {
            return graph.edgeSet().size();
        }
    };
}

public static <V,E>IsomorphicGraphMapping<V,E> identity(Graph<V,E> graph){
    if (graph == null) {
        throw new IllegalArgumentException("Graph cannot be null");
    }
    return new IsomorphicGraphMapping<V, E>() {
        @Override
        public V getVertexCorrespondence(V vertex, boolean forward) {
            if (vertex == null || !graph.containsVertex(vertex)) {
                throw new IllegalArgumentException("Vertex is not part of the graph");
            }
            return vertex;
        }

        @Override
        public E getEdgeCorrespondence(E edge, boolean forward) {
            if (edge == null || !graph.containsEdge(edge)) {
                throw new IllegalArgumentException("Edge is not part of the graph");
            }
            return edge;
        }

        @Override
        public GraphMapping<V, E> getInverse() {
            return this; // Identity is its own inverse
        }

        @Override
        public boolean isRefinedBy(GraphMapping<V, E> mapping) {
            return true; // Identity is always a refinement of any mapping
        }
    };
}

