public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    if (out == null || message == null || schema == null || buffer == null) {
        throw new IllegalArgumentException("Arguments cannot be null");
    }
    if (buffer.start != buffer.offset) {
        throw new IllegalArgumentException("Buffer must be at its start when passed to writeDelimitedTo");
    }

    // Get the size of the message
    int size = schema.getSerializedSize(message, buffer);
    int messageSizeLength = ProtobufVarintVarinthelper.computeRawVarint32Size(size);

    // Prepare the buffer for the message size
    LinkedBuffer messageSizeBuffer = new LinkedBuffer(messageSizeLength);
    try {
        // Write the size of the message to the size buffer
        ProtobufVarintVarinthelper.writeRawVarint32(size, messageSizeBuffer);

        // Write the size to the output stream
        out.write(messageSizeBuffer.buffer, 0, messageSizeLength);

        // Write the message to the output stream
        schema.writeTo(out, message, buffer);

        // The total size written is the size of the message plus the size of the size
        return size + messageSizeLength;
    } finally {
        // Recycle the buffer used for the message size
        buffer.clear();
        messageSizeBuffer.clear();
    }
}

public static <T>int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    if (out == null) {
        throw new IllegalArgumentException("OutputStream cannot be null");
    }
    if (message == null) {
        throw new IllegalArgumentException("Message cannot be null");
    }
    if (schema == null) {
        throw new IllegalArgumentException("Schema cannot be null");
    }
    if (buffer == null) {
        throw new IllegalArgumentException("LinkedBuffer cannot be null");
    }

    try {
        // Serialize the message to the buffer
        final int size = schema.writeTo(buffer, message);

        // Write the size of the message as a varint
        LinkedBuffer varintBuffer = LinkedBuffer.allocate(10); // Varint can be up to 10 bytes
        try {
            ProtobufOutput varintOutput = new ProtobufOutput(varintBuffer);
            varintOutput.writeRawVarInt32(size);

            // Write the varint size to the output stream
            out.write(varintBuffer.buffer, 0, varintOutput.size());

            // Write the actual message to the output stream
            out.write(buffer.buffer, 0, size);

            // Return the total size written (varint size + message size)
            return varintOutput.size() + size;
        } finally {
            // Always deallocate the varint buffer
            LinkedBuffer deallocate = varintBuffer;
            while (deallocate != null) {
                LinkedBuffer next = deallocate.next;
                LinkedBuffer.deallocate(deallocate);
                deallocate = next;
            }
        }
    } finally {
        // Deallocate the buffer used for serialization
        if (buffer.next == null) {
            LinkedBuffer.deallocate(buffer);
        } else {
            LinkedBuffer deallocate = buffer.next;
            buffer.next = null; // help GC
            while (deallocate != null) {
                LinkedBuffer next = deallocate.next;
                LinkedBuffer.deallocate(deallocate);
                deallocate = next;
            }
        }
    }
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    if (out == null || message == null || schema == null || buffer == null) {
        throw new IllegalArgumentException("Output stream, message, schema, and buffer cannot be null");
    }

    try {
        final byte[] messageData = schema.writeTo(buffer, message);
        final int size = messageData.length;

        // Write the size as a varint
        ProtostuffIOUtil.writeRawVarint32(out, size);

        // Write the actual message data
        out.write(messageData);

        return size;
    } catch (Exception e) {
        throw new IOException("Error writing message to output stream", e);
    } finally {
        // Reset the buffer for reuse
        buffer.clear();
    }
}

