private static int writeVarint32To(OutputStream out, int value) throws IOException {
    int size = 0;
    while ((value & 0xFFFFFF80) != 0) {
        out.write((value & 0x7F) | 0x80);
        value >>>= 7;
        size++;
    }
    out.write(value);
    size++;
    return size;
}

