static long compressTimeBucket(long timeBucket, int dayStep) {
    if (dayStep <= 0) {
        throw new IllegalArgumentException("dayStep must be greater than 0");
    }
    if (timeBucket < 10000000 || timeBucket > 99991231) {
        throw new IllegalArgumentException("timeBucket must be a valid date in the format YYYYMMDD");
    }

    int year = (int) (timeBucket / 10000);
    int monthDay = (int) (timeBucket % 10000);
    int month = monthDay / 100;
    int day = monthDay % 100;

    int[] daysInMonth = {31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};

    // Adjust for leap year
    if (month == 2 && (year % 4 == 0 && (year % 100 != 0 || year % 400 == 0))) {
        daysInMonth[1] = 29;
    }

    int dayOfYear = 0;
    for (int m = 0; m < month - 1; m++) {
        dayOfYear += daysInMonth[m];
    }
    dayOfYear += day;

    int compressedDayOfYear = (dayOfYear / dayStep) * dayStep;

    int compressedMonth = 1;
    int compressedDay = 0;
    while (compressedMonth <= 12) {
        if (compressedDayOfYear <= daysInMonth[compressedMonth - 1]) {
            compressedDay = compressedDayOfYear;
            break;
        }
        compressedDayOfYear -= daysInMonth[compressedMonth - 1];
        compressedMonth++;
    }

    return year * 10000 + compressedMonth * 100 + compressedDay;
}

static long compressTimeBucket(long timeBucket, int dayStep) {
    if (dayStep <= 0) {
        throw new IllegalArgumentException("dayStep must be greater than 0");
    }
    if (timeBucket <= 0) {
