    // Calculate the day of the year
    int[] daysInMonth = {31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
    if ((year % 4 == 0 && year % 100 != 0) || (year % 400 == 0)) {
        daysInMonth[1] = 29; // Leap year
    }

    int dayOfYear = 0;
    for (int i = 0; i < month - 1; i++) {
        dayOfYear += daysInMonth[i];
    }
    dayOfYear += day;

    // Calculate the new day of the year by rounding down to the nearest dayStep
    int compressedDayOfYear = (dayOfYear - 1) / dayStep * dayStep + 1;

    // Convert the new day of the year back to month and day
    int compressedMonth = 0;
    while (compressedDayOfYear > daysInMonth[compressedMonth]) {
        compressedDayOfYear -= daysInMonth[compressedMonth];
        compressedMonth++;
    }
    int compressedDay = compressedDayOfYear;

    // Reconstruct the compressed time bucket
    int compressedMonthDay = (compressedMonth + 1) * 100 + compressedDay;
    return year * 10000L + compressedMonthDay;
}

static long compressTimeBucket(long timeBucket, int dayStep) {
    try {
        if (dayStep <= 0) {
            throw new IllegalArgumentException("dayStep must be greater than 0");
        }

        int year = (int) (timeBucket / 10000);
        int month = (int) ((timeBucket % 10000) / 100);
        int day = (int) (timeBucket % 100);

        if (year < 1000 || year > 9999 || month < 1 || month > 12 || day < 1 || day > 31) {
            throw new IllegalArgumentException("Invalid timeBucket format or value");
        }

        // Calculate the day of the year
        int[] daysInMonth = {31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
        if (month == 2 && ((year % 4 == 0 && year % 100 != 0) || (year % 400 == 0))) {
            daysInMonth[1] = 29; // Leap year
        }

        int dayOfYear = 0;
        for (int i = 0; i < month - 1; i++) {
            dayOfYear += daysInMonth[i];
        }
        dayOfYear += day;

        // Find the start day of the bucket
        int startDayOfYear = (dayOfYear - 1) / dayStep * dayStep + 1;

        // Convert startDayOfYear back to year, month, day
        int startMonth = 0;
        int startDay = startDayOfYear;
        for (int i = 0; i < 12; i++) {
            if (startDay <= daysInMonth[i]) {
                startMonth = i + 1;
                break;
            }
            startDay -= daysInMonth[i];
        }

        // Handle the case where the resulting day is 0 (which means it should be the last day of the previous month)
        if (startDay == 0) {
            startMonth--;
            if (startMonth == 0) {
                startMonth = 12;
                year--;
            }
            startDay = daysInMonth[startMonth - 1];
        }

        return (year * 10000L + startMonth * 100L + startDay);
    } catch (Exception e) {
        throw new RuntimeException("Error in compressTimeBucket", e);
    }
}

