                lastDayOfMonth = 31;
                break;
            case 4: case 6: case 9: case 11:
                lastDayOfMonth = 30;
                break;
            case 2:
                if ((year % 4 == 0 && year % 100 != 0) || (year % 400 == 0)) {
                    lastDayOfMonth = 29; // Leap year
                } else {
                    lastDayOfMonth = 28;
                }
                break;
            default:
                throw new IllegalArgumentException("Invalid month in timeBucket.");
        }

        // Calculate the adjusted day based on dayStep
        int adjustedDay = ((day - 1) / dayStep) * dayStep + 1;

        // Ensure the adjusted day is within the month range
        if (adjustedDay > lastDayOfMonth) {
            adjustedDay = lastDayOfMonth;
        }

        // Return the reformatted time bucket
        return year * 10000L + month * 100L + adjustedDay;
    } catch (Exception e) {
