        throw new IllegalArgumentException("timeBucket contains invalid month or day");
    }

    // Calculate the new day by rounding down to the nearest dayStep
    int newDay = (day - 1) / dayStep * dayStep + 1;

    // Adjust for months with fewer than 31 days
    int[] daysInMonth = {31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
    if (newDay > daysInMonth[month - 1]) {
        newDay = daysInMonth[month - 1];
    }

    return year * 10000 + month * 100 + newDay;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null) {
        throw new IllegalArgumentException("Input string cannot be null");
    }
    if (index < 0 || len < 0) {
        throw new IllegalArgumentException("Index and length must be non-negative");
    }
    if (index + len > str.length()) {
        throw new IllegalArgumentException("Index and length must specify a valid range within the string");
    }

    int size = 0;
    for (int i = index; i < index + len; i++) {
        char ch = str.charAt(i);
        if (ch <= 0x7F) {
            size += 1;
        } else if (ch <= 0x7FF) {
            size += 2;
        } else if (Character.isHighSurrogate(ch) && i + 1 < index + len && Character.isLowSurrogate(str.charAt(i + 1))) {
            size += 4; // surrogate pair
            i++; // skip the low surrogate
        } else {
            size += 3;
        }
    }
    return size;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null) {
        throw new IllegalArgumentException("Input string cannot be null");
    }
    if (index < 0 || len < 0 || index + len > str.length()) {
        throw new IllegalArgumentException("Index and length must be within the bounds of the string");
    }

    int size = 0;
    for (int i = index; i < index + len; i++) {
        char ch = str.charAt(i);
        if (ch <= 0x7F) {
            size++;
        } else if (ch <= 0x7FF) {
            size += 2;
        } else if (Character.isSurrogate(ch)) {
            if (i + 1 >= index + len) {
                throw new IllegalArgumentException("Invalid surrogate pair at index " + i);
            }
            char nextCh = str.charAt(i + 1);
            if (!Character.isSurrogatePair(ch, nextCh)) {
                throw new IllegalArgumentException("Invalid surrogate pair at index " + i);
            }
            size += 4; // Valid surrogate pair
            i++; // Skip the next character as it's part of the surrogate pair
        } else {
            size += 3;
        }
    }
    return size;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null) {
        throw new IllegalArgumentException("Input string cannot be null");
    }
    if (index < 0 || len < 0 || index + len > str.length()) {
        throw new IndexOutOfBoundsException("Invalid index or length");
    }

    int size = 0;
    for (int i = index; i < index + len; i++) {
        char ch = str.charAt(i);
        if (ch <= 0x7F) {
            size += 1;
        } else if (ch <= 0x7FF) {
            size += 2;
        } else if (Character.isHighSurrogate(ch)) {
            if (i + 1 < index + len) {
                char nextChar = str.charAt(i + 1);
                if (Character.isLowSurrogate(nextChar)) {
                    size += 4;
                    i++; // Skip the low surrogate
                } else {
                    throw new IllegalArgumentException("Invalid UTF-16 surrogate pair");
                }
            } else {
                throw new IllegalArgumentException("Incomplete surrogate pair at end of string");
            }
        } else {
            size += 3;
        }
    }
    return size;
}

