        if (ch <= 0x7F) {
            size += 1;
        } else if (ch <= 0x7FF) {
            size += 2;
        } else if (Character.isHighSurrogate(ch)) {
            if (i + 1 < index + len) {
                char nextCh = str.charAt(i + 1);
                if (Character.isLowSurrogate(nextCh)) {
                    size += 4; // surrogate pair forms a valid code point
                    i++; // skip the next character as it's part of the surrogate pair
                } else {
                    size += 3; // unpaired high surrogate
                }
            } else {
                size += 3; // unpaired high surrogate at the end
            }
        } else {
            size += 3;
        }
    }
    return size;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null) {
        throw new IllegalArgumentException("Input string cannot be null");
    }
    if (index < 0 || len < 0 || index + len > str.length()) {
        throw new IndexOutOfBoundsException("Invalid index or length specified");
    }

    int size = 0;
    for (int i = index; i < index + len; i++) {
        char ch = str.charAt(i);
        if (ch <= 0x7F) {
            size += 1;
        } else if (ch <= 0x7FF) {
            size += 2;
        } else if (Character.isHighSurrogate(ch)) {
            if (i + 1 < index + len && Character.isLowSurrogate(str.charAt(i + 1))) {
                size += 4; // Valid surrogate pair
                i++; // Skip the next character as it's part of the surrogate pair
            } else {
                throw new IllegalArgumentException("Invalid surrogate pair at index: " + i);
            }
        } else if (Character.isLowSurrogate(ch)) {
            throw new IllegalArgumentException("Unmatched low surrogate at index: " + i);
        } else {
            size += 3;
        }
    }
    return size;
}

