            }
            utf8Length += 4;
            i++; // Skip the next character as it is part of the surrogate pair
        } else {
            utf8Length += 3;
        }
    }

    LinkedBuffer buffer = lb;
    int offset = 0;
    try {
        for (int i = 0; i < str.length(); i++) {
            char c = str.charAt(i);
            if (c < 0x80) {
                ensureCapacity(buffer, session, offset, 1);
                buffer.buffer[buffer.start + offset++] = (byte) c;
            } else if (c < 0x800) {
