                buffer.buffer[buffer.start + offset++] = (byte) (0xc0 | (c >> 6));
                buffer.buffer[buffer.start + offset++] = (byte) (0x80 | (c & 0x3f));
            } else if (Character.isSurrogate(c)) {
                char nextChar = str.charAt(i + 1);
                int codePoint = Character.toCodePoint(c, nextChar);
                ensureCapacity(buffer, session, offset, 4);
                buffer.buffer[buffer.start + offset++] = (byte) (0xf0 | (codePoint >> 18));
                buffer.buffer[buffer.start + offset++] = (byte) (0x80 | ((codePoint >> 12) & 0x3f));
                buffer.buffer[buffer.start + offset++] = (byte) (0x80 | ((codePoint >> 6) & 0x3f));
                buffer.buffer[buffer.start + offset++] = (byte) (0x80 | (codePoint & 0x3f));
                i++; // Skip the next character as it is part of the surrogate pair
            } else {
                ensureCapacity(buffer, session, offset, 3);
                buffer.buffer[buffer.start + offset++] = (byte) (0xe0 | (c >> 12));
                buffer.buffer[buffer.start + offset++] = (byte) (0x80 | ((c >> 6) & 0x3f));
                buffer.buffer[buffer.start + offset++] = (byte) (0x80 | (c & 0x3f));
            }
        }
    } catch (IOException e) {
