    }
    if (session == null) {
        throw new IllegalArgumentException("WriteSession cannot be null");
    }
    if (lb == null) {
        throw new IllegalArgumentException("LinkedBuffer cannot be null");
    }

    try {
        int length = str.length();
        int size = 0;
        for (int i = 0; i < length; i++) {
            char c = str.charAt(i);
            if (c <= 0x7F) {
                size += 1;
            } else if (c <= 0x7FF) {
                size += 2;
            } else if (Character.isHighSurrogate(c)) {
                if (i + 1 < length && Character.isLowSurrogate(str.charAt(i + 1))) {
                    size += 4;
                    i++;
                } else {
                    throw new IllegalArgumentException("Unpaired surrogate at index " + i);
                }
            } else {
                size += 3;
            }
        }

        byte[] bytes = PlatformDependent.allocateUnpooledBuffer(size + 3, true);
        bytes[0] = (byte) ((size >>> 16) & 0xFF);
        bytes[1] = (byte) ((size >>> 8) & 0xFF);
        bytes[2] = (byte) (size & 0xFF);

        int offset = 3;
        for (int i = 0; i < length; i++) {
            char c = str.charAt(i);
            if (c <= 0x7F) {
                bytes[offset++] = (byte) c;
            } else if (c <= 0x7FF) {
                bytes[offset++] = (byte) (0xC0 | (c >>> 6));
                bytes[offset++] = (byte) (0x80 | (c & 0x3F));
            } else if (Character.isHighSurrogate(c)) {
                if (i + 1 < length && Character.isLowSurrogate(str.charAt(i + 1))) {
                    int codePoint = Character.toCodePoint(c, str.charAt(i + 1));
                    bytes[offset++] = (byte) (0xF0 | (codePoint >>> 18));
                    bytes[offset++] = (byte) (0x80 | ((codePoint >>> 12) & 0x3F));
                    bytes[offset++] = (byte) (0x80 | ((codePoint >>> 6) & 0x3F));
                    bytes[offset++] = (byte) (0x80 | (codePoint & 0x3F));
                    i++;
                } else {
                    throw new IllegalArgumentException("Unpaired surrogate at index " + i);
                }
            } else {
                bytes[offset++] = (byte) (0xE0 | (c >>> 12));
                bytes[offset++] = (byte) (0x80 | ((c >>> 6) & 0x3F));
                bytes[offset++] = (byte) (0x80 | (c & 0x3F));
            }
        }

        return lb.buffer(bytes);
    } catch (Exception e) {
        throw new RuntimeException("Error writing UTF-8 string to LinkedBuffer", e);
    }
}

public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    if (str == null) {
        throw new IllegalArgumentException("Input string cannot be null");
    }
    if (session == null) {
        throw new IllegalArgumentException("WriteSession cannot be null");
    }
    if (lb == null) {
        throw new IllegalArgumentException("LinkedBuffer cannot be null");
    }

    final int length = str.length();
    int offset = 0;
    final int size = lb.size();

    try {
        for (int i = 0; i < length; i++) {
            char c = str.charAt(i);

            if (c < 0x80) {
                if (offset + 1 > size) {
                    lb = lb.next(LinkedBuffer.allocate(session, 8192));
                    offset = 0;
                }
                lb.buffer[offset++] = (byte) c;
            } else if (c < 0x800) {
                if (offset + 2 > size) {
                    lb = lb.next(LinkedBuffer.allocate(session, 8192));
                    offset = 0;
                }
                lb.buffer[offset++] = (byte) (0xC0 | (c >> 6));
                lb.buffer[offset++] = (byte) (0x80 | (c & 0x3F));
            } else if (c < 0xD800 || c >= 0xE000) {
                if (offset + 3 > size) {
                    lb = lb.next(LinkedBuffer.allocate(session, 8192));
                    offset = 0;
                }
                lb.buffer[offset++] = (byte) (0xE0 | (c >> 12));
                lb.buffer[offset++] = (byte) (0x80 | ((c >> 6) & 0x3F));
                lb.buffer[offset++] = (byte) (0x80 | (c & 0x3F));
            } else {
                // surrogate pair
                if (i + 1 >= length) {
                    throw new IllegalArgumentException("Invalid UTF-16 sequence");
                }
                char c2 = str.charAt(i + 1);
                if (c >= 0xDC00 || c2 < 0xDC00 || c2 >= 0xE000) {
                    throw new IllegalArgumentException("Invalid UTF-16 surrogate pair");
                }
                i++;

                int codePoint = 0x010000 + ((c & 0x03FF) << 10) + (c2 & 0x03FF);

                if (offset + 4 > size) {
                    lb = lb.next(LinkedBuffer.allocate(session, 8192));
                    offset = 0;
                }
                lb.buffer[offset++] = (byte) (0xF0 | (codePoint >> 18));
                lb.buffer[offset++] = (byte) (0x80 | ((codePoint >> 12) & 0x3F));
                lb.buffer[offset++] = (byte) (0x80 | ((codePoint >> 6) & 0x3F));
                lb.buffer[offset++] = (byte) (0x80 | (codePoint & 0x3F));
            }
        }
        lb.limit(offset);
    } catch (Exception e) {
        throw new RuntimeException("Error writing UTF-8 to LinkedBuffer", e);
    }

    return lb;
}

