    }

    int totalSize = 0;
    while (node != null) {
        int fragmentSize = node.start == -1 ? node.offset : node.offset - node.start;
        out.write(node.buffer, node.start == -1 ? 0 : node.start, fragmentSize);
        totalSize += fragmentSize;
        node = node.next;
    }
    return totalSize;
}

