protected int removeUnusedNodes() {
    if (root == null) {
        return 0;
    }

    int removedNodes = 0;
    Queue<CategoryNode> queue = new LinkedList<>();
    queue.add(root);

    while (!queue.isEmpty()) {
        CategoryNode currentNode = queue.poll();

        if (currentNode.isActive()) {
            Iterator<CategoryNode> iterator = currentNode.getChildren().iterator();
            while (iterator.hasNext()) {
                CategoryNode childNode = iterator.next();
                if (!childNode.isActive()) {
                    iterator.remove();
                    removedNodes++;
                } else {
                    queue.add(childNode);
                }
            }
        } else {
            // If the current node is inactive, remove it from its parent's children
            if (currentNode.getParent() != null) {
                currentNode.getParent().getChildren().remove(currentNode);
                removedNodes++;
            }
        }
    }

    return removedNodes;
}

