    }

    OuterFaceCirculator circulator = new OuterFaceCirculator(start, dir);

    do {
        if (predicate.test(circulator.getCurrentNode())) {
            return circulator;
        }
        if (circulator.getCurrentNode() == stop) {
            return circulator;
        }
        circulator.advance();
    } while (circulator.getCurrentNode() != start);

