    while (!circulator.getNode().equals(stop)) {
        if (predicate.test(circulator.getNode())) {
            return circulator;
        }
        if (!circulator.hasNext()) {
            throw new IllegalStateException("Reached the end of the outer face without finding a matching node or stopping node");
