    if (tour.isEmpty()) {
        return new GraphPathImpl<>(graph, null, Collections.emptyList(), 0.0);
    }

    List<E> pathEdges = new ArrayList<>(tour);
    V startVertex = graph.getEdgeSource(pathEdges.get(0));
    List<V> vertexPath = new ArrayList<>();
    vertexPath.add(startVertex);

    try {
        for (E edge : pathEdges) {
            V source = graph.getEdgeSource(edge);
            V target = graph.getEdgeTarget(edge);
            if (vertexPath.get(vertexPath.size() - 1).equals(source)) {
                vertexPath.add(target);
            } else if (vertexPath.get(vertexPath.size() - 1).equals(target)) {
                vertexPath.add(source);
            } else {
                throw new IllegalArgumentException("Edges do not form a valid path");
            }
        }
    } catch (IllegalArgumentException e) {
        throw new IllegalArgumentException("Tour does not represent a valid path in the graph", e);
