protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Tour and graph cannot be null");
    }
    if (tour.isEmpty()) {
        return new GraphPathImpl<>(graph, null, new ArrayList<>(), 0.0);
    }

    Map<V, List<E>> adjacencyList = new HashMap<>();
    for (E edge : tour) {
        V source = graph.getEdgeSource(edge);
        V target = graph.getEdgeTarget(edge);
        adjacencyList.computeIfAbsent(source, k -> new ArrayList<>()).add(edge);
        adjacencyList.computeIfAbsent(target, k -> new ArrayList<>()).add(edge);
    }

    V startVertex = null;
    for (Map.Entry<V, List<E>> entry : adjacencyList.entrySet()) {
        if (entry.getValue().size() == 1) {
            startVertex = entry.getKey();
            break;
        }
    }

    if (startVertex == null) {
        throw new IllegalArgumentException("Tour does not form a path");
    }

    List<E> pathEdges = new ArrayList<>();
    Stack<V> stack = new Stack<>();
    stack.push(startVertex);

    while (!stack.isEmpty()) {
        V current = stack.peek();
        List<E> edges = adjacencyList.get(current);

        if (edges != null && !edges.isEmpty()) {
            E nextEdge = edges.remove(0);
            pathEdges.add(nextEdge);
            V nextVertex = graph.getEdgeSource(nextEdge) == current ? graph.getEdgeTarget(nextEdge) : graph.getEdgeSource(nextEdge);
            stack.push(nextVertex);
        } else {
            stack.pop();
        }
    }

    return new GraphPathImpl<>(graph, startVertex, pathEdges, calculatePathWeight(pathEdges, graph));
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Tour and graph must not be null");
    }

    if (tour.isEmpty()) {
        return new GraphPathImpl<>(graph, null, 0, Collections.emptyList());
    }

    List<E> edgeList = new ArrayList<>(tour);
    V startVertex = null;
    Map<V, V> vertexPredecessors = new HashMap<>();

    for (E edge : edgeList) {
        V source = graph.getEdgeSource(edge);
        V target = graph.getEdgeTarget(edge);

        if (startVertex == null) {
            startVertex = source;
        }

        vertexPredecessors.put(target, source);
    }

    List<E> pathEdges = new ArrayList<>();
    List<V> pathVertices = new ArrayList<>();

    V currentVertex = startVertex;
    pathVertices.add(currentVertex);

    while (vertexPredecessors.containsKey(currentVertex)) {
        V predecessor = vertexPredecessors.get(currentVertex);
        E edge = graph.getEdge(predecessor, currentVertex);
        pathEdges.add(edge);
        pathVertices.add(currentVertex);
        currentVertex = predecessor;
    }

    // Close the path if it's a cycle
    if (vertexPredecessors.get(startVertex) != null && pathVertices.get(0).equals(pathVertices.get(pathVertices.size() - 1))) {
        pathEdges.add(graph.getEdge(pathVertices.get(pathVertices.size() - 2), startVertex));
    }

    double weight = 0;
    for (E edge : pathEdges) {
        weight += graph.getEdgeWeight(edge);
    }

    return new GraphPathImpl<>(graph, startVertex, weight, pathEdges, pathVertices);
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Tour and graph cannot be null");
    }
    if (tour.isEmpty()) {
        throw new IllegalArgumentException("Tour cannot be empty");
    }

    List<E> edgeList = new ArrayList<>(tour);
    List<V> vertexList = new ArrayList<>();
    Map<V, Integer> vertexDegree = new HashMap<>();

    // Calculate the degree of each vertex
    for (E edge : edgeList) {
        V source = graph.getEdgeSource(edge);
        V target = graph.getEdgeTarget(edge);
        vertexDegree.put(source, vertexDegree.getOrDefault(source, 0) + 1);
        vertexDegree.put(target, vertexDegree.getOrDefault(target, 0) + 1);
    }

    // Find a starting vertex (a vertex with an odd degree if exists, otherwise any vertex)
    V startVertex = null;
    for (Map.Entry<V, Integer> entry : vertexDegree.entrySet()) {
        if (entry.getValue() % 2 != 0) {
            startVertex = entry.getKey();
            break;
        }
    }
    if (startVertex == null) {
        startVertex = graph.getEdgeSource(edgeList.get(0));
    }

    // Reconstruct the path
    Deque<E> stack = new ArrayDeque<>();
    List<E> path = new ArrayList<>();
    stack.push(edgeList.remove(0));

    while (!stack.isEmpty()) {
        V currentVertex = graph.getEdgeTarget(stack.peek());
        List<E> edges = new ArrayList<>(graph.edgesOf(currentVertex));

        if (!edges.isEmpty()) {
            E nextEdge = edges.stream().filter(edgeList::contains).findFirst().orElse(null);
            if (nextEdge != null) {
                stack.push(nextEdge);
                edgeList.remove(nextEdge);
            }
        } else {
            path.add(stack.pop());
        }
    }

    // Construct the vertex list from the edge path
    V lastVertex = null;
    for (E edge : path) {
        if (lastVertex == null) {
            vertexList.add(graph.getEdgeSource(edge));
        }
        vertexList.add(graph.getEdgeTarget(edge));
        lastVertex = graph.getEdgeTarget(edge);
    }

    return new GraphPathImpl<>(graph, vertexList.get(0), vertexList.get(vertexList.size() - 1), vertexList, path, path.stream().map(graph::getEdgeWeight).mapToDouble(Double::doubleValue).sum());
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Tour and graph must not be null");
    }
    if (tour.isEmpty()) {
        return new GraphPathImpl<>(graph, null, null, 0.0);
    }

    List<E> edgeList = new ArrayList<>(tour);
    V startVertex = null;
    V endVertex = null;

    try {
        Map<V, Integer> degreeMap = new HashMap<>();
        for (E edge : edgeList) {
            V source = graph.getEdgeSource(edge);
            V target = graph.getEdgeTarget(edge);

            degreeMap.put(source, degreeMap.getOrDefault(source, 0) + 1);
            degreeMap.put(target, degreeMap.getOrDefault(target, 0) + 1);
        }

        for (Map.Entry<V, Integer> entry : degreeMap.entrySet()) {
            if (entry.getValue() == 1) {
                if (startVertex == null) {
                    startVertex = entry.getKey();
                } else {
                    endVertex = entry.getKey();
                }
            }
        }

        if (startVertex == null || endVertex == null) {
            throw new IllegalArgumentException("The provided edges do not form a valid tour");
        }

        List<V> vertexList = new ArrayList<>();
        vertexList.add(startVertex);

        Set<E> visitedEdges = new HashSet<>();
        V currentVertex = startVertex;

        while (currentVertex != null) {
            E nextEdge = null;
            for (E edge : edgeList) {
                if (!visitedEdges.contains(edge) && (graph.getEdgeSource(edge).equals(currentVertex) || graph.getEdgeTarget(edge).equals(currentVertex))) {
                    nextEdge = edge;
                    break;
                }
            }

            if (nextEdge == null) {
                break;
            }

            visitedEdges.add(nextEdge);
            if (graph.getEdgeSource(nextEdge).equals(currentVertex)) {
                currentVertex = graph.getEdgeTarget(nextEdge);
            } else {
                currentVertex = graph.getEdgeSource(nextEdge);
            }

            if (!vertexList.contains(currentVertex)) {
                vertexList.add(currentVertex);
            }
        }

        if (!vertexList.contains(endVertex) || !visitedEdges.containsAll(edgeList)) {
            throw new IllegalArgumentException("The provided edges do not form a valid tour");
        }

        return new GraphPathImpl<>(graph, startVertex, endVertex, edgeList, graph.getType().isWeighted() ? edgeList.stream().mapToDouble(graph::getEdgeWeight).sum() : 0.0);
    } catch (Exception e) {
        throw new IllegalArgumentException("Error processing the edge set to form a tour", e);
    }
}

