public static void selectRow(int row, JTable table, JScrollPane pane) {
    if (table == null || pane == null || table.getParent() != pane.getViewport()) {
        throw new IllegalArgumentException("Table must belong to the specified JScrollPane");
    }
    int rowCount = table.getRowCount();
    if (row < 0 || row >= rowCount) {
        throw new IllegalArgumentException("Row index out of bounds");
    }

    try {
        table.getSelectionModel().setSelectionInterval(row, row);
        Rectangle cellRect = table.getCellRect(row, 0, true);
        pane.getViewport().scrollRectToVisible(cellRect);
        // Delay repaint to ensure the table properly paints the newly selected row
        table.repaint(100);
    } catch (Exception e) {
        e.printStackTrace();
    }
}

public static void selectRow(int row, JTable table, JScrollPane pane) {
    try {
        if (table == null || pane == null) {
            throw new IllegalArgumentException("Table and JScrollPane cannot be null");
        }

        if (row < 0 || row >= table.getRowCount()) {
            throw new IllegalArgumentException("Row index is out of bounds");
        }

        // Select the specified row
        table.setRowSelectionInterval(row, row);

        // Scroll the JScrollPane to the newly selected row
        Rectangle cellRect = table.getCellRect(row, 0, true);
        pane.getViewport().scrollRectToVisible(cellRect);

        // Repaint the table with a delay to ensure the selection is visible
        table.repaint(cellRect);

        // Additional delay to ensure painting completes
        try {
            Thread.sleep(100); // Delay for 100 milliseconds
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }

        table.repaint();
    } catch (Exception e) {
        e.printStackTrace();
    }
}

