        int newCapacity = Math.max(requiredCapacity, this.data.length * 2);
        byte[] newData = new byte[newCapacity];
        System.arraycopy(this.data, 0, newData, 0, this.length);
        this.data = newData;
    }
    this.data[this.length++] = (byte) (intValue >> 24);
    this.data[this.length++] = (byte) (intValue >> 16);
    this.data[this.length++] = (byte) (intValue >> 8);
    this.data[this.length++] = (byte) intValue;
