        throw new IllegalArgumentException("StringBuffer cannot be null");
    }
    if (nameStart < 0) {
        throw new IllegalArgumentException("nameStart cannot be negative");
    }
    if (nameStart >= buf.length()) {
        // If nameStart is beyond the length of the buffer, do nothing
        return;
    }

    int end = nameStart + 1; // Start looking for the next uppercase letter or end of buffer
    while (end < buf.length() && Character.isLowerCase(buf.charAt(end))) {
        end++;
    }

    if (end > nameStart + 1) {
        // Append the first letter and the character at 'end' (if it's uppercase or end of buffer)
        buf.append(buf.charAt(nameStart)).append(buf.charAt(end - 1));
        // Delete the abbreviated part from the buffer
        buf.delete(nameStart + 1, end - 1);
    }
}

