private void pop(final String descriptor) {
    if (descriptor == null) {
        throw new IllegalArgumentException("Descriptor cannot be null");
    }

    // Check if the descriptor is a method descriptor
    if (descriptor.startsWith("(")) {
        int endOfArguments = descriptor.indexOf(')');
        if (endOfArguments == -1) {
            throw new IllegalArgumentException("Invalid method descriptor: missing ')'");
        }

        String argumentTypes = descriptor.substring(1, endOfArguments);
        int index = 0;
        while (index < argumentTypes.length()) {
            char c = argumentTypes.charAt(index);
            switch (c) {
                case 'B': case 'C': case 'F': case 'I': case 'S': case 'Z':
                    // These are single-byte types
                    index++;
                    popOneSlot();
                    break;
                case 'J': case 'D':
                    // These are double-byte types
                    index++;
                    popTwoSlots();
                    break;
                case 'L':
                    // Object reference
                    index = argumentTypes.indexOf(';', index);
                    if (index == -1) {
                        throw new IllegalArgumentException("Invalid class descriptor: missing ';'");
                    }
                    index++;
                    popOneSlot();
                    break;
                case '[':
                    // Array
                    do {
                        index++;
                    } while (index < argumentTypes.length() && argumentTypes.charAt(index) == '[');
                    if (index == argumentTypes.length()) {
                        throw new IllegalArgumentException("Invalid array descriptor: no element type");
                    }
                    c = argumentTypes.charAt(index);
                    if (c == 'L') {
                        index = argumentTypes.indexOf(';', index);
                        if (index == -1) {
                            throw new IllegalArgumentException("Invalid class descriptor: missing ';'");
                        }
                    }
                    index++;
                    popOneSlot();
                    break;
                default:
                    throw new IllegalArgumentException("Invalid descriptor character: " + c);
            }
        }
    } else {
        // Handle field descriptor
        char c = descriptor.charAt(0);
        switch (c) {
            case 'B': case 'C': case 'F': case 'I': case 'S': case 'Z':
                popOneSlot();
                break;
            case 'J': case 'D':
                popTwoSlots();
                break;
            case 'L':
                if (descriptor.indexOf(';') != descriptor.length() - 1) {
                    throw new IllegalArgumentException("Invalid class descriptor: missing ';'");
                }
                popOneSlot();
                break;
            case '[':
                // Validate array descriptor
