                char elementType = descriptor.charAt(lastBracket + 1);
                if (elementType == 'L' && descriptor.charAt(descriptor.length() - 1) != ';') {
                    throw new IllegalArgumentException("Invalid array descriptor: missing ';'");
                }
                popOneSlot();
                break;
